import re

def anti_shuffle(s):
    # Split the string into words and spaces, preserving all spaces
    tokens = re.findall(r'\S+|\s+', s)
    result = []
    for token in tokens:
        if token.isspace():
            # Keep spaces as is
            result.append(token)
        else:
            # Sort characters of the token
            sorted_token = ''.join(sorted(token))
            result.append(sorted_token)
    return ''.join(result)

