def parse_nested_parens(text):
    groups = text.split()
    result = []
    for group in groups:
        depth = 0
        max_depth = 0
        for char in group:
            if char == '(':
                depth += 1
                if depth > max_depth:
                    max_depth = depth
            else:  # char == ')'
                depth -= 1
        result.append(max_depth)
    return result

